export function appendHaltEvent(eventsPath, { role, ts, reason, probes, agreed, rate, tau, specialist_summary, claude_summary }) {
  appendEvent(eventsPath, {
    kind: "halt",
    role,
    ts,
    data: {
      reason,
      probes,
      agreed,
      rate,
      tau,
      ...(specialist_summary ? { specialist_summary } : {}),
      ...(claude_summary ? { claude_summary } : {}),
    },
  });
}

def is_ship_pin(obj):
    """A pin requires ship:true at or under ship_bar. Missing ship is not a pin."""
    if not isinstance(obj, dict):
        return False
    if obj.get("scored") is False:
        return False
    if obj.get("ship") is not True:
        return False
    if obj.get("status") == "andon":
        return False
    bar = obj.get("ship_bar")
    if not isinstance(bar, int):
        return False
    fc = obj.get("false_conformant_total")
    if not isinstance(fc, int) or fc > bar:
        return False
    return True

